() => {
  // Find all Add to Cart buttons/links
  const addToCartElements = document.querySelectorAll('a.ajax_add_to_cart_button, a[title="Add to cart"], .ajax_add_to_cart_button, button[name="Submit"]');

  // Find all Quick View elements
  const quickViewElements = document.querySelectorAll('a.quick-view, .quick-view');

  // Get product containers
  const productContainers = document.querySelectorAll('.product-container');

  // Analyze first product container
  let firstProductHTML = '';
  if (productContainers.length > 0) {
    firstProductHTML = productContainers[0].innerHTML.substring(0, 2000);
  }

  return {
    addToCartCount: addToCartElements.length,
    addToCartLocators: Array.from(addToCartElements).slice(0, 3).map(el => ({
      tag: el.tagName,
      class: el.className,
      title: el.title,
      href: el.href,
      dataId: el.getAttribute('data-id-product')
    })),
    quickViewCount: quickViewElements.length,
    productContainerCount: productContainers.length,
    firstProductHTML: firstProductHTML
  };
}

() => {
    // Find product 5 container (in-stock item)
    const productContainers = document.querySelectorAll('.product-container');
    const product5 = productContainers[4]; // 0-indexed, product 5 is index 4

    if (!product5) return { error: 'Product 5 container not found' };

    // Trigger mouseover event
    const event = new MouseEvent('mouseover', { bubbles: true, cancelable: true });
    product5.dispatchEvent(event);

    // Wait a moment and find Add to Cart button
    const addToCartBtn = product5.querySelector('.ajax_add_to_cart_button');
    const quickView = product5.querySelector('.quick-view');

    return {
        productName: product5.querySelector('.product-name')?.innerText || 'Unknown',
        addToCartButton: addToCartBtn ? {
            tag: addToCartBtn.tagName,
            class: addToCartBtn.className,
            title: addToCartBtn.title,
            text: addToCartBtn.innerText,
            disabled: addToCartBtn.classList.contains('disabled'),
            dataIdProduct: addToCartBtn.getAttribute('data-id-product')
        } : null,
        quickView: quickView ? {
            tag: quickView.tagName,
            class: quickView.className,
            href: quickView.href
        } : null
    };
}

() => {
    const products = document.querySelectorAll('.product-container');
    const results = [];

    products.forEach((product, index) => {
        const name = product.querySelector('.product-name')?.innerText || 'Unknown';
        const addBtn = product.querySelector('.ajax_add_to_cart_button');
        const availability = product.querySelector('.availability')?.innerText || 
                            product.querySelector('[class*="availability"]')?.innerText || '';

        results.push({
            index: index + 1,
            name: name.trim(),
            addToCartClass: addBtn?.className || 'NOT FOUND',
            isDisabled: addBtn?.classList.contains('disabled') || false,
            availability: availability.trim()
        });
    });

    return {
        totalProducts: products.length,
        products: results,
        enabledAddToCartCount: results.filter(p => !p.isDisabled).length
    };
}

() => {
    const addToCartBtn = document.querySelector('#add_to_cart button, .exclusive, button[name="Submit"]');
    const quantityInput = document.querySelector('#quantity_wanted');
    const sizeSelect = document.querySelector('#group_1');
    const colorPicker = document.querySelector('#color_to_pick_list');
    const selectedColor = document.querySelector('#color_to_pick_list .selected, #color_to_pick_list a.selected');

    return {
        addToCartButton: addToCartBtn ? {
            tag: addToCartBtn.tagName,
            id: addToCartBtn.id,
            class: addToCartBtn.className,
            name: addToCartBtn.name,
            type: addToCartBtn.type,
            text: addToCartBtn.innerText.trim(),
            disabled: addToCartBtn.disabled,
            cssSelector: addToCartBtn.id ? '#' + addToCartBtn.id : '.' + addToCartBtn.className.split(' ').join('.')
        } : null,
        quantityInput: quantityInput ? {
            id: quantityInput.id,
            name: quantityInput.name,
            type: quantityInput.type,
            value: quantityInput.value
        } : null,
        sizeSelect: sizeSelect ? {
            id: sizeSelect.id,
            name: sizeSelect.name,
            selectedValue: sizeSelect.value,
            options: Array.from(sizeSelect.options).map(o => ({ value: o.value, text: o.text }))
        } : null,
        colorPickerSelector: '#color_to_pick_list a',
        availableColors: colorPicker ? Array.from(colorPicker.querySelectorAll('a')).map(a => ({
            name: a.getAttribute('name'),
            id: a.id,
            class: a.className,
            isSelected: a.classList.contains('selected')
        })) : []
    };
}

