() => {
    // More specific search for Add to Cart button
    const buttons = document.querySelectorAll('button, input[type="submit"], .button');
    const addToCartCandidates = [];

    buttons.forEach(btn => {
        const text = btn.innerText || btn.value || '';
        if (text.toLowerCase().includes('add to cart') || 
            btn.name === 'Submit' || 
            btn.classList.contains('exclusive')) {
            addToCartCandidates.push({
                tag: btn.tagName,
                id: btn.id,
                class: btn.className,
                name: btn.name,
                type: btn.type,
                text: text.trim().substring(0, 50),
                parentId: btn.parentElement?.id || '',
                parentClass: btn.parentElement?.className || ''
            });
        }
    });

    // Also check for the specific p.submit element
    const submitP = document.querySelector('#add_to_cart p.submit, p.submit');
    const submitButton = submitP?.querySelector('button');

    return {
        candidates: addToCartCandidates,
        submitButton: submitButton ? {
            tag: submitButton.tagName,
            id: submitButton.id,
            class: submitButton.className,
            name: submitButton.name,
            type: submitButton.type,
            text: submitButton.innerText.trim(),
            cssSelector: 'p.submit button, #add_to_cart button.exclusive'
        } : null,
        addToCartDiv: document.querySelector('#add_to_cart') ? {
            id: 'add_to_cart',
            innerHTML: document.querySelector('#add_to_cart').innerHTML.substring(0, 500)
        } : null
    };
}

